import http from 'node:http';
import { validDueDate } from './public/dates.js';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'notes')) {
  db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'deleted')) {
  db.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Remember a position even while a task belongs to a different project.
// Seed current positions for databases created before return-order support.
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id),
  project_id INTEGER NOT NULL REFERENCES projects(id),
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id),
  UNIQUE (project_id, position)
);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, position FROM tasks`);
const rememberedPosition = db.prepare('SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?');
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberPosition = db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)');
function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const listTasks = db.prepare('SELECT id, project_id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? ORDER BY position, id');
const getTask = db.prepare('SELECT id, project_id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title, priority, position) VALUES (?, ?, ?, ?)');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const setNotes = db.prepare('UPDATE tasks SET notes = ? WHERE project_id = ? AND id = ?');
const setDeleted = db.prepare('UPDATE tasks SET deleted = ? WHERE project_id = ? AND id = ?');
const taskJSON = task => ({ ...task, completed: Boolean(task.completed), deleted: Boolean(task.deleted) });
const projectSelect = `SELECT p.id, p.name, p.archived, p.default_priority,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND deleted = 0) AS total,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND deleted = 0 AND completed = 1) AS completed
  FROM projects p`;
const listProjects = db.prepare(`${projectSelect} ORDER BY p.id`);
const getProject = db.prepare(`${projectSelect} WHERE p.id = ?`);
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/dates.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/dates.js', import.meta.url))]],
  ['/search.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/search.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readInput(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (request.method === 'GET' && path === '/api/projects') {
      return json(response, 200, listProjects.all());
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (request.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return json(response, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (request.method === 'PATCH' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      if (!project) return json(response, 404, { error: 'Project not found' });
      const input = await readInput(request);
      if (input && Object.hasOwn(input, 'name')) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(response, 400, { error: 'Project name is required' });
        renameProject.run(name, project.id);
      } else if (input && Object.hasOwn(input, 'default_priority')) {
        if (project.archived) return json(response, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, project.id);
      } else {
        if (typeof input?.archived !== 'boolean') return json(response, 400, { error: 'Archived must be a boolean' });
        updateProject.run(Number(input.archived), project.id);
      }
      return json(response, 200, getProject.get(projectMatch[1]));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = getProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project' });
      }
      if (request.method === 'GET' && !taskId) {
        return json(response, 200, listTasks.all(projectId).map(taskJSON));
      }
      if (request.method === 'POST' && !taskId) {
        const input = await readInput(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const taskId = transaction(() => {
          const { position } = nextPosition.get(projectId);
          const result = createTask.run(projectId, title, project.default_priority, position);
          rememberPosition.run(result.lastInsertRowid, projectId, position);
          return result.lastInsertRowid;
        });
        return json(response, 201, taskJSON(getTask.get(projectId, taskId)));
      }
      if (request.method === 'PATCH' && taskId) {
        const task = getTask.get(projectId, taskId);
        if (!task) return json(response, 404, { error: 'Task not found' });
        const input = await readInput(request);
        if (input && Object.hasOwn(input, 'deleted')) {
          if (typeof input.deleted !== 'boolean') return json(response, 400, { error: 'Deleted must be a boolean' });
          setDeleted.run(Number(input.deleted), projectId, taskId);
          return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
        }
        if (task.deleted) return json(response, 409, { error: 'Deleted task must be restored before editing' });
        if (input && Object.hasOwn(input, 'destination_project_id')) {
          const destinationId = input.destination_project_id;
          if (!Number.isSafeInteger(destinationId) || destinationId === project.id) {
            return json(response, 400, { error: 'Choose another active project' });
          }
          const destination = getProject.get(destinationId);
          if (!destination) return json(response, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(response, 409, { error: 'Archived destination project' });
          transaction(() => {
            let saved = rememberedPosition.get(taskId, destinationId);
            if (!saved) {
              saved = nextPosition.get(destinationId);
              rememberPosition.run(taskId, destinationId, saved.position);
            }
            moveTask.run(destinationId, saved.position, projectId, taskId);
          });
          return json(response, 200, taskJSON(getTask.get(destinationId, taskId)));
        } else if (input && Object.hasOwn(input, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || (date !== '' && !validDueDate(date))) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setDueDate.run(date, projectId, taskId);
        } else if (input && Object.hasOwn(input, 'notes')) {
          if (typeof input.notes !== 'string') {
            return json(response, 400, { error: 'Notes must be text' });
          }
          setNotes.run(input.notes, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') return json(response, 400, { error: 'Completion must be a boolean' });
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return json(response, 200, taskJSON(getTask.get(projectId, taskId)));
      }
    }
    if (request.method === 'POST' && path === '/api/projects') {
      const input = await readInput(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(response, 201, getProject.get(result.lastInsertRowid));
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    if (!response.headersSent) json(response, error.status || 500, { error: error.status ? error.message : 'Unable to complete request' });
    else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => server.close(() => {
    db.close();
    process.exit(0);
  }));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runInNewContext } from 'node:vm';
import { validDueDate, matchesDueRange } from '../public/dates.js';
import { matchesSearch } from '../public/search.js';

// Minimal DOM harness for exercising the real browser event handlers without dependencies.
class Element {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this.textContent = '';
    this._value = undefined;
  }
  append(...children) {
    for (const child of children) child.parent = this;
    this.children.push(...children);
  }
  remove() { this.parent.children = this.parent.children.filter(child => child !== this); }
  replaceChildren(...children) { this.children = children; }
  setAttribute(name, value) { this.attributes[name] = value; }
  addEventListener(name, handler) { this.listeners[name] = handler; }
  async fire(name) { await this.listeners[name]({ preventDefault() {} }); }
  focus() {}
  get value() { return this._value ?? (this.tag === 'select' ? this.children[0]?.textContent : '') ?? ''; }
  set value(value) { this._value = value; }
  querySelector(selector) {
    for (const child of this.children) {
      if (selector === '[role="alert"]' ? child.attributes.role === 'alert' :
        selector.startsWith('#') ? child.id === selector.slice(1) : child.tag === selector) return child;
      const nested = child.querySelector(selector);
      if (nested) return nested;
    }
    return null;
  }
  querySelectorAll(selector) {
    const tags = selector.split(',').map(tag => tag.trim());
    return this.children.flatMap(child => [
      ...(tags.includes(child.tag) ? [child] : []),
      ...child.querySelectorAll(selector),
    ]);
  }
  set innerHTML(html) {
    this.children = [];
    const stack = [this];
    for (const token of html.match(/<[^>]+>|[^<]+/g)) {
      if (token.startsWith('</')) { stack.pop(); continue; }
      if (token.startsWith('<')) {
        const tag = token.match(/^<(\w+)/)[1];
        const element = new Element(tag);
        element.id = token.match(/id="([^"]+)"/)?.[1];
        stack.at(-1).append(element);
        if (tag !== 'input') stack.push(element);
      } else {
        stack.at(-1).textContent += token.trim();
      }
    }
  }
}

async function fixture(archived = false, destinations = [
  { id: 1, name: 'Source', archived: false },
  { id: 2, name: 'Destination', archived: false },
  { id: 3, name: 'Archived', archived: true },
  { id: 4, name: 'Other destination', archived: false },
], beforeRead = async () => {}, deletedIds = []) {
  const app = new Element('main');
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'High' },
    { id: 2, title: 'Second', completed: true, priority: 'Normal' },
    { id: 3, title: 'Third', completed: true, priority: 'High' },
    { id: 4, title: 'Fourth', completed: false, priority: 'Low' },
  ].map(task => ({ ...task, due_date: '', notes: '', deleted: deletedIds.includes(task.id) }));
  const requests = [];
  const project = { id: 1, archived, default_priority: 'Normal' };
  const source = await readFile(new URL('../public/app.js', import.meta.url), 'utf8');
  const context = {
    validDueDate, matchesDueRange, matchesSearch,
    document: { querySelector: () => app, createElement: tag => new Element(tag) },
    fetch: async (path, options) => {
      if (!options) {
        await beforeRead(app, path);
        return { ok: true, json: async () => structuredClone(path === '/api/projects' ? destinations : tasks) };
      }
      requests.push(options);
      if (path === '/api/projects/1') {
        Object.assign(project, JSON.parse(options.body));
        return { ok: true, json: async () => structuredClone(project) };
      }
      if (options.method === 'POST') {
        const task = { id: tasks.length + 1, ...JSON.parse(options.body), completed: false, priority: project.default_priority, notes: '' };
        tasks.push(task);
        return { ok: true, json: async () => structuredClone(task) };
      }
      const task = tasks.find(item => item.id === Number(path.split('/').at(-1)));
      const input = JSON.parse(options.body);
      if (input.destination_project_id) {
        task.project_id = input.destination_project_id;
      } else {
        Object.assign(task, input);
      }
      return { ok: true, json: async () => structuredClone(task) };
    },
  };
  runInNewContext(source.slice(0, source.lastIndexOf('\nrender().catch')).replace(/^import .*;\n/gm, '') + '\nthis.renderTasks = renderTasks;', context);
  await context.renderTasks({ ...project });
  const completion = app.querySelector('#task-filter');
  const priority = app.querySelector('#priority-filter');
  const rows = () => app.querySelector('#task-list').children;
  const titles = () => rows().map(row => row.children[0].textContent);
  return { app, completion, priority, rows, titles, requests, tasks, project };
}

async function choose(select, value) {
  select.value = value;
  await select.fire('change');
}

test('deletion and restoration retain intersecting filters and disable deleted-row edits', async () => {
  const f = await fixture();
  assert.deepEqual(f.completion.children.map(option => option.textContent), ['All', 'Open', 'Completed', 'Deleted']);
  const dueForm = f.rows()[0].children[4];
  dueForm.children[1].value = '2025-01-15';
  await dueForm.fire('submit');
  const notesForm = f.rows()[0].children[6];
  notesForm.children[1].value = '  saved\nnotes  ';
  await notesForm.fire('submit');
  await choose(f.completion, 'Open');
  await choose(f.priority, 'High');
  f.app.querySelector('#due-from').value = '2025-01-01';
  f.app.querySelector('#due-through').value = '2025-01-31';
  await f.app.querySelector('#due-range-form').fire('submit');
  f.app.querySelector('#task-search').value = 'first';
  await f.app.querySelector('#task-search-form').fire('submit');
  const before = structuredClone(f.tasks[0]);
  assert.equal(f.rows()[0].children[7].textContent, 'Delete task');
  await f.rows()[0].children[7].fire('click');
  assert.deepEqual(f.titles(), []);
  assert.deepEqual(f.tasks[0], { ...before, deleted: true });
  assert.equal(f.completion.value, 'Open');
  for (const value of ['All', 'Open', 'Completed']) {
    await choose(f.completion, value);
    assert.deepEqual(f.titles(), []);
  }
  await choose(f.completion, 'Deleted');
  assert.deepEqual(f.titles(), ['First']);
  const deleted = f.rows()[0];
  assert.equal(deleted.children[7].textContent, 'Restore task');
  assert.equal(deleted.children[7].disabled, false);
  for (const control of deleted.querySelectorAll('input, textarea, select, button')) {
    if (control !== deleted.children[7]) assert.equal(control.disabled, true);
  }
  assert.equal(deleted.children[6].children[1].value, before.notes);
  await choose(f.priority, 'Low');
  assert.deepEqual(f.titles(), []);
  await choose(f.priority, 'High');
  f.app.querySelector('#task-search').value = 'missing';
  await f.app.querySelector('#task-search-form').fire('submit');
  assert.deepEqual(f.titles(), []);
  f.app.querySelector('#task-search').value = 'first';
  await f.app.querySelector('#task-search-form').fire('submit');
  await f.rows()[0].children[7].fire('click');
  assert.deepEqual(f.titles(), []);
  assert.equal(f.completion.value, 'Deleted');
  assert.equal(f.priority.value, 'High');
  assert.equal(f.app.querySelector('#due-from').value, '2025-01-01');
  assert.equal(f.app.querySelector('#due-through').value, '2025-01-31');
  assert.equal(f.app.querySelector('#task-search').value, 'first');
  assert.deepEqual(f.tasks[0], before);
  await choose(f.completion, 'Open');
  assert.deepEqual(f.titles(), ['First']);
  assert.equal(f.rows()[0].children[1].disabled, false);
});

test('archived projects keep deleted tasks readable but cannot delete or restore', async () => {
  const archived = await fixture(true, undefined, undefined, [2]);
  for (const row of archived.rows()) {
    assert.equal(row.children[7].disabled, true);
    await row.children[7].fire('click');
  }
  await choose(archived.completion, 'Deleted');
  assert.deepEqual(archived.titles(), ['Second']);
  assert.equal(archived.rows()[0].children[7].textContent, 'Restore task');
  for (const control of archived.rows()[0].querySelectorAll('input, textarea, select, button')) {
    assert.equal(control.disabled, true);
  }
  await archived.rows()[0].children[7].fire('click');
  await choose(archived.priority, 'High');
  assert.deepEqual(archived.titles(), []);
  await choose(archived.priority, 'Normal');
  assert.deepEqual(archived.titles(), ['Second']);
  assert.equal(archived.requests.length, 0);
});

test('notes save exact plain text while preserving all applied filters and membership', async () => {
